# Recovery cashflow valuation and conditional loss-given-default models.
.cr_lgd_scalar <- function(value,name,minimum=NULL) {a<-.cr_numeric(value,name);if(length(a)!=1L||!is.null(dim(a))||(!is.null(minimum)&&a<minimum)) .cr_error('LGD_INPUT',paste(name,'requires a scalar in its stated domain'));as.numeric(a)}
.cr_lgd_currency <- function(currency,context) {.cr_string(currency,'currency','INVALID_CURRENCY');ctx<-.cr_result(NULL,'lgd.context',context=context)$context;if(!is.null(ctx$currency)&&!identical(ctx$currency,currency)) .cr_error('TARGET_MISMATCH','Context currency conflicts with reporting currency');ctx}
discount_recoveries <- function(cashflows,discount_curve,fx_contract,default_date,evaluation_cutoff,reporting_currency,context=NULL) {
 ctx<-.cr_lgd_currency(reporting_currency,context);default<-.cr_data_date(default_date,'default_date');cutoff<-.cr_data_date(evaluation_cutoff,'evaluation_cutoff');if(default>cutoff) .cr_error('RECOVERY_DATE','Default follows evaluation cutoff')
 if(!.cr_object(discount_curve)||!.cr_object(fx_contract)) .cr_error('RECOVERY_CONTRACT','Explicit discount and FX objects required')
 .cr_data_required(discount_curve,c('anchor_date','known_at','discount_basis','points'));.cr_data_required(fx_contract,c('reporting_currency','known_at','conversion_basis','rates'))
 if(.cr_data_date(discount_curve$anchor_date,'anchor_date')!=default||.cr_data_date(discount_curve$known_at,'curve known_at')>cutoff) .cr_error('RECOVERY_CONTRACT','Curve must be anchored at default and known at cutoff')
 if(!is.character(discount_curve$discount_basis)||length(discount_curve$discount_basis)!=1L||!nzchar(trimws(discount_curve$discount_basis))) .cr_error('RECOVERY_CONTRACT','Document the economic discount basis')
 .cr_string(fx_contract$conversion_basis,'conversion_basis','RECOVERY_CONTRACT');if(!identical(fx_contract$reporting_currency,reporting_currency)||!(fx_contract$conversion_basis %in% c('cashflow_date','default_date'))||.cr_data_date(fx_contract$known_at,'FX known_at')>cutoff) .cr_error('RECOVERY_CONTRACT','FX convention or knowledge cutoff incompatible')
 points<-.cr_data_rows(discount_curve$points,'discount points');.cr_data_unique(points,'cashflow_date','discount points');df<-list()
 for(row in points){.cr_data_required(row,'discount_factor');date<-.cr_data_date(row$cashflow_date,'cashflow_date');factor<-.cr_lgd_scalar(row$discount_factor,'discount_factor',0);if(date<default||(date==default&&factor!=1)) .cr_error('RECOVERY_CONTRACT','Discount anchor factor must be one and points cannot precede default');df[[row$cashflow_date]]<-factor}
 rates<-.cr_data_rows(fx_contract$rates,'FX rates');.cr_data_unique(rates,c('currency','date'),'FX rates');fx<-list()
 for(row in rates){.cr_data_required(row,'rate');.cr_data_date(row$date,'FX date');rate<-.cr_lgd_scalar(row$rate,'FX rate',0);if(rate<=0||(row$currency==reporting_currency&&rate!=1)) .cr_error('RECOVERY_CONTRACT','Positive FX rates and reporting-currency identity required');fx[[.cr_data_key(row,c('currency','date'))]]<-rate}
 flows<-.cr_data_rows(cashflows,'cashflows');.cr_data_unique(flows,'cashflow_id','cashflows');included<-excluded<-list();recoveries<-costs<-numeric()
 for(row in flows) {
  .cr_data_required(row,c('cashflow_date','known_at','currency','kind','amount'));date<-.cr_data_date(row$cashflow_date,'cashflow_date');known<-.cr_data_date(row$known_at,'known_at');amount<-.cr_lgd_scalar(row$amount,'cashflow amount',0);.cr_string(row$currency,'cashflow currency','INVALID_CURRENCY')
  if(date<default||known<date) .cr_error('RECOVERY_DATE','Realized cashflow cannot precede default or knowledge precede realization');if(!(row$kind %in% c('RECOVERY','DIRECT_COST','INDIRECT_COST'))) .cr_error('RECOVERY_KIND','Declare RECOVERY, DIRECT_COST or INDIRECT_COST')
  if(date>cutoff||known>cutoff){excluded[[length(excluded)+1L]]<-list(cashflow_id=row$cashflow_id,reason=if(date>cutoff)'FUTURE_CASHFLOW' else 'NOT_YET_KNOWN');next}
  fx_date<-if(fx_contract$conversion_basis=='default_date')default_date else row$cashflow_date;key<-.cr_data_key(list(currency=row$currency,date=fx_date),c('currency','date'))
  if(is.null(df[[row$cashflow_date]])) .cr_error('MISSING_DISCOUNT','Exact cashflow-date discount factor missing');if(is.null(fx[[key]])) .cr_error('MISSING_FX','Explicit currency/date FX rate missing')
  value<-.cr_loss_multiply(amount,fx[[key]],df[[row$cashflow_date]]);if(row$kind=='RECOVERY')recoveries<-c(recoveries,value) else costs<-c(costs,value)
  included[[length(included)+1L]]<-list(cashflow_id=row$cashflow_id,cashflow_date=row$cashflow_date,known_at=row$known_at,kind=row$kind,original_currency=row$currency,amount=amount,fx_date=fx_date,fx_rate=fx[[key]],discount_factor=df[[row$cashflow_date]],discounted_contribution=if(row$kind=='RECOVERY')value else -value)
 }
 gross<-.cr_loss_sum(recoveries);cost<-.cr_loss_sum(costs);net<-.cr_loss_sum(c(gross,-cost))
 .cr_result(list(discounted_gross_recoveries=gross,discounted_costs=cost,discounted_net_recoveries=net,contributions=included,excluded_cashflows=excluded),'lgd.discount_recoveries',reporting_currency,ctx,diagnostics=list(default_date=default_date,evaluation_cutoff=evaluation_cutoff,discount_basis=discount_curve$discount_basis,fx_conversion_basis=fx_contract$conversion_basis,input_fingerprint=.cr_hash(list(cashflows=flows,discount_curve=discount_curve,fx_contract=fx_contract))),limitations='Only realized and known cashflows are included. Explicit curve/FX data determine the economic valuation convention; no regulatory discount rate or future recovery is supplied.')
}
workout_lgd <- function(ead_at_default,discounted_net_recoveries,episode_status,default_date,evaluation_cutoff,currency,context=NULL) {
 ctx<-.cr_lgd_currency(currency,context);ead<-.cr_lgd_scalar(ead_at_default,'ead_at_default',0);if(.cr_data_date(default_date,'default_date')>.cr_data_date(evaluation_cutoff,'evaluation_cutoff')) .cr_error('RECOVERY_DATE','Default follows evaluation cutoff')
 if(!is.character(episode_status)||length(episode_status)!=1L||!(episode_status %in% c('OPEN','CLOSED'))) .cr_error('WORKOUT_STATUS','Declare OPEN or CLOSED')
 if(inherits(discounted_net_recoveries,'CalcResult')) {r<-discounted_net_recoveries;if(!identical(r$method_id,'lgd.discount_recoveries')||!identical(r$unit,currency)||!identical(r$diagnostics$default_date,default_date)||!identical(r$diagnostics$evaluation_cutoff,evaluation_cutoff)) .cr_error('TARGET_MISMATCH','Recovery result and workout valuation convention differ');net<-.cr_lgd_scalar(r$value$discounted_net_recoveries,'discounted_net_recoveries')} else net<-.cr_lgd_scalar(discounted_net_recoveries,'discounted_net_recoveries')
 loss<-.cr_loss_sum(c(ead,-net));ratio<-if(ead==0)NULL else loss/ead;if(!is.null(ratio)&&!is.finite(ratio)) .cr_error('NUMERICAL_FAILURE','LGD ratio outside finite range')
 .cr_result(list(ead_at_default=ead,discounted_net_recoveries=net,economic_loss=loss,economic_lgd_to_date=ratio,economic_lgd=if(episode_status=='CLOSED')ratio else NULL,episode_status=episode_status,complete=episode_status=='CLOSED',denominator_status=if(ead==0)'ZERO_EAD' else 'DEFINED',remaining_recovery_estimated=FALSE),'lgd.workout_lgd','loss_fraction',ctx,diagnostics=list(currency=currency,default_date=default_date,evaluation_cutoff=evaluation_cutoff),limitations='Raw economic LGD may be negative or above one. An open workout has a loss-to-date ratio, not an observed final LGD. Zero EAD leaves the ratio undefined.')
}

.cr_lgd_fit_inputs <- function(X,y,feature_order,fit_intercept,weights,weight_type,target,training,model_id,model_version,method_id) {
 des<-.cr_glm_design(X,feature_order,fit_intercept);x<-des$x;d<-des$d;y<-.cr_numeric(y,'lgd_targets',vector_only=TRUE)
 if(length(y)!=nrow(x)) .cr_error('INCOMPATIBLE_SHAPE','One target per training row required')
 if(!identical(weight_type,'frequency')) .cr_error('INVALID_WEIGHT_TYPE','Declare integer frequency weights')
 w<-if(is.null(weights))rep(1,length(y)) else .cr_numeric(weights,'weights',vector_only=TRUE)
 if(length(w)!=length(y)||any(w<0)||any(w!=floor(w))||!any(w>0)||!is.finite(sum(w))||sum(w)>2^53-1) .cr_error('INVALID_WEIGHTS','Nonnegative exact integer frequencies with positive finite total required')
 if(!.cr_object(training)||!identical(training$workout_population,'closed_defaulted_episodes')) .cr_error('LGD_POPULATION','Training must declare workout_population=closed_defaulted_episodes')
 if(!.cr_object(target)||(!identical(target$probability_measure,'PHYSICAL')||!identical(target$conditioning,'given_default'))) .cr_error('INCOMPATIBLE_TARGET','Empirical LGD requires a physical target conditional on default')
 model<-.cr_model(list(schema_version='1.0',model_id=model_id,model_version=model_version,method_id=method_id,feature_order=as.list(des$feature_order),parameters=.cr_empty_object(),preprocessing=list(transformation='identity'),target=target,training=training,diagnostics=.cr_empty_object(),provenance=list(data_origin=if(is.null(training$data_origin))'USER_SUPPLIED' else training$data_origin,parameter_origin='ESTIMATED')))
 active<-w>0;s<-svd(d[active,,drop=FALSE],nu=0,nv=0)$d;if(length(s)<ncol(d)||tail(s,1)<=s[1]*1e-10) .cr_error('RANK_DEFICIENT','LGD mean design requires full rank at relative tolerance1e-10')
 model$training_input_fingerprint<-.cr_hash(list(X=.cr_lgd_matrix_rows(x),y=as.list(y),weights=as.list(w)))
 model$parameters<-list(fit_intercept=fit_intercept,default_condition='given_default',feature_min=as.list(apply(x[active,,drop=FALSE],2,min)),feature_max=as.list(apply(x[active,,drop=FALSE],2,max)),weight_type=weight_type)
 list(model=model,x=x,d=d,y=y,w=w,active=active)
}
.cr_lgd_controls<-function(max_iter,tolerance){if(length(max_iter)!=1L||is.logical(max_iter)||!is.numeric(max_iter)||!is.finite(max_iter)||max_iter<1||max_iter!=floor(max_iter)) .cr_error('INVALID_INPUT','max_iter must be a positive integer');t<-.cr_lgd_scalar(tolerance,'tolerance');if(t<=0||t>=1) .cr_error('INVALID_INPUT','tolerance must lie in (0,1)');t}
.cr_lgd_separation<-function(d,y){boundary<-y==0|y==1;if(!any(boundary))return(0);scaled<-sweep(d,2,apply(abs(d),2,max),'/');signed<-scaled[boundary,,drop=FALSE]*(2*y[boundary]-1);interior<-scaled[!boundary,,drop=FALSE];k<-ncol(d);a<-cbind(signed,-signed);eq<-cbind(interior,-interior)
 fit<-lpSolve::lp('max',colMeans(a),rbind(a,eq,cbind(diag(k),diag(k))),c(rep('>=',nrow(a)),rep('=',nrow(eq)),rep('<=',k)),c(rep(0,nrow(a)+nrow(eq)),rep(1,k)))
 if(fit$status!=0) .cr_error('NUMERICAL_FAILURE','Fractional separation certificate failed');objective<-mean(as.vector(a%*%fit$solution));if(objective>1e-8) .cr_error('SEPARATION','Endpoint observations permit an unbounded coefficient direction while interior rows remain fixed');objective}
.cr_lgd_fractional_solution<-function(d,y,w,fit_intercept,max_iter,tolerance){separation<-.cr_lgd_separation(d,y);total<-sum(w);beta<-rep(0,ncol(d));m<-sum(w*y)/total;if(fit_intercept){if(m<=0||m>=1) .cr_error('NUMERICAL_FAILURE','Fractional initial weighted mean rounded to a boundary');beta[1]<-qlogis(m)}
 objective<-function(b){eta<-as.vector(d%*%b);sum(w*(pmax(eta,0)+log1p(exp(-abs(eta)))-y*eta))/total}
 for(iteration in 0:max_iter){eta<-as.vector(d%*%beta);p<-plogis(eta);gradient<-as.vector(crossprod(d,w*(p-y)))/total;h<-crossprod(d,d*(w*p*(1-p)))/total;if(max(abs(gradient))<=tolerance)break;if(iteration==max_iter) .cr_error('NON_CONVERGENCE','Fractional likelihood score exceeds tolerance');step<-tryCatch(solve(h,gradient),error=function(e).cr_error('NON_IDENTIFIABLE','Fractional information singular'));before<-objective(beta);scale<-1
 while(scale>2^-40&&objective(beta-scale*step)>before-1e-4*scale*sum(gradient*step))scale<-scale/2
 if(scale<=2^-40) .cr_error('NON_CONVERGENCE','Fractional Newton line search failed');beta<-beta-scale*step}
 p<-plogis(as.vector(d%*%beta));info<-crossprod(d,d*(w*p*(1-p)));bread<-tryCatch({chol(info);solve(info)},error=function(e).cr_error('NON_IDENTIFIABLE','Fractional fitted information singular'));if(any(p<=0|p>=1)||any(!is.finite(bread))) .cr_error('NUMERICAL_FAILURE','Fractional fit reached a numerical probability boundary');list(beta=beta,p=p,bread=bread,iteration=iteration,separation=separation)}
fit_fractional_lgd<-function(X_train,lgd_targets,feature_order,link,covariance,target,training,model_id,model_version,weights=NULL,weight_type='frequency',fit_intercept=TRUE,max_iter=200,tolerance=1e-10,context=NULL){
 if(!identical(link,'logit')) .cr_error('UNSUPPORTED_LINK','Fractional LGD currently uses the explicit logit mean link');if(!(covariance%in%c('HC0','HC1'))) .cr_error('INVALID_COVARIANCE','Use HC0 or HC1 under independent observations');tolerance<-.cr_lgd_controls(max_iter,tolerance)
 q<-.cr_lgd_fit_inputs(X_train,lgd_targets,feature_order,fit_intercept,weights,weight_type,target,training,model_id,model_version,'lgd.fit_fractional_lgd');if(any(q$y<0|q$y>1)) .cr_error('INVALID_LGD_TARGET','Fractional targets must lie in [0,1]; no clipping is performed');d<-q$d[q$active,,drop=FALSE];y<-q$y[q$active];w<-q$w[q$active];f<-.cr_lgd_fractional_solution(d,y,w,fit_intercept,max_iter,tolerance);n<-sum(w);k<-ncol(d)
 if(covariance=='HC1'&&n<=k) .cr_error('NON_IDENTIFIABLE','HC1 requires frequency total greater than parameter count');meat<-crossprod(d,d*(w*(y-f$p)^2));cov<-f$bread%*%meat%*%f$bread*(if(covariance=='HC1')n/(n-k) else 1)
 diagnostics<-list(converged=TRUE,iterations=f$iteration,quasi_log_likelihood=sum(w*(y*log(f$p)+(1-y)*log1p(-f$p))),frequency_total=n,n_active_rows=length(y),rank=k,maximum_mean_score=max(abs(crossprod(d,w*(y-f$p))/n)),separation_mean_margin=f$separation,covariance_type=covariance,weight_type=weight_type,solver='damped_newton',max_iter=max_iter,tolerance=tolerance,distribution_identified=FALSE)
 model<-q$model;model$parameters<-c(model$parameters,list(link=link,coefficients=as.list(f$beta),covariance=.cr_lgd_matrix_rows(cov),covariance_type=covariance));model$diagnostics<-diagnostics;.cr_fit_result(.cr_model(model),'lgd.fit_fractional_lgd',diagnostics=diagnostics,context=context)
}
.cr_lgd_precision_design<-function(precision_design,precision_feature_order,n){if(is.null(precision_design)){if(length(precision_feature_order)) .cr_error('FEATURE_MISMATCH','Constant precision has no predictor names');return(list(x=matrix(numeric(),n,0),d=matrix(1,n,1),feature_order=character()))};z<-.cr_glm_design(precision_design,precision_feature_order,TRUE);if(nrow(z$x)!=n) .cr_error('INCOMPATIBLE_SHAPE','Precision design must match mean-design rows');z}
.cr_lgd_beta_statistics<-function(theta,d,z,y,w){k<-ncol(d);mu<-plogis(as.vector(d%*%theta[seq_len(k)]));phi<-exp(as.vector(z%*%theta[k+seq_len(ncol(z))]));a<-mu*phi;b<-(1-mu)*phi;ly<-log(y);ln<-log1p(-y);ll<-lgamma(phi)-lgamma(a)-lgamma(b)+(a-1)*ly+(b-1)*ln
 u<-ly-ln-digamma(a)+digamma(b);v<-digamma(phi)-mu*digamma(a)-(1-mu)*digamma(b)+mu*ly+(1-mu)*ln;derivative<-mu*(1-mu);gb<-phi*derivative*u;gg<-phi*v;gradient<-colSums(cbind(d*gb,z*gg)*w);ta<-trigamma(a);tb<-trigamma(b)
 hbb<-phi^2*derivative^2*(ta+tb)-phi*derivative*(1-2*mu)*u;hbg<- -derivative*phi*(u+phi*(-mu*ta+(1-mu)*tb));hgg<- -phi*v-phi^2*(trigamma(phi)-mu^2*ta-(1-mu)^2*tb)
 information<-rbind(cbind(crossprod(d,d*(w*hbb)),crossprod(d,z*(w*hbg))),cbind(crossprod(z,d*(w*hbg)),crossprod(z,z*(w*hgg))));list(ll=sum(w*ll),gradient=gradient,information=information,mu=mu,phi=phi)}
fit_beta_lgd<-function(X_train,lgd_targets,feature_order,mean_link,precision_link,target,training,model_id,model_version,precision_design=NULL,precision_feature_order=NULL,weights=NULL,weight_type='frequency',fit_intercept=TRUE,max_iter=500,tolerance=1e-10,context=NULL){
 if(!identical(mean_link,'logit')||!identical(precision_link,'log')) .cr_error('UNSUPPORTED_LINK','Declare logit mean and log precision links');tolerance<-.cr_lgd_controls(max_iter,tolerance);q<-.cr_lgd_fit_inputs(X_train,lgd_targets,feature_order,fit_intercept,weights,weight_type,target,training,model_id,model_version,'lgd.fit_beta_lgd');if(any(q$y<=0|q$y>=1)) .cr_error('INVALID_LGD_TARGET','Beta targets must lie strictly inside (0,1); boundaries need a separate model')
 zz<-.cr_lgd_precision_design(precision_design,precision_feature_order,length(q$y));d<-q$d[q$active,,drop=FALSE];y<-q$y[q$active];w<-q$w[q$active];z<-zz$d[q$active,,drop=FALSE];s<-svd(z,nu=0,nv=0)$d;if(length(s)<ncol(z)||tail(s,1)<=s[1]*1e-10) .cr_error('RANK_DEFICIENT','Precision design requires full rank');f<-.cr_lgd_fractional_solution(d,y,w,fit_intercept,max_iter,tolerance);residual<-sum(w*(y-f$p)^2)/sum(w);if(residual<=1e-24) .cr_error('NON_IDENTIFIABLE','No residual interior dispersion; beta precision has no finite estimate')
 initial_phi<-max(.1,sum(w*f$p*(1-f$p))/sum(w)/residual-1);theta<-c(f$beta,log(initial_phi),rep(0,ncol(z)-1));total<-sum(w)
 objective<-function(b){v<-suppressWarnings(.cr_lgd_beta_statistics(b,d,z,y,w));if(!is.finite(v$ll)||any(!is.finite(v$gradient)))return(.Machine$double.xmax);-v$ll/total};gradient<-function(b){v<-suppressWarnings(.cr_lgd_beta_statistics(b,d,z,y,w));if(any(!is.finite(v$gradient)))return(rep(0,length(b)));-v$gradient/total}
 fit<-optim(theta,objective,gradient,method='BFGS',control=list(maxit=max_iter,reltol=tolerance^2));v<-.cr_lgd_beta_statistics(fit$par,d,z,y,w);score<-max(abs(v$gradient)/total);if(!is.finite(v$ll)||!is.finite(score)||score>max(sqrt(tolerance),1e-7)) .cr_error('NON_CONVERGENCE','Beta likelihood score exceeds tolerance',list(solver_status=fit$convergence,maximum_mean_score=score));covariance<-tryCatch({chol(v$information);solve(v$information)},error=function(e).cr_error('NON_IDENTIFIABLE','Observed beta information is not positive definite'));if(any(!is.finite(covariance))||any(v$mu<=0|v$mu>=1)||any(!is.finite(v$phi))) .cr_error('NUMERICAL_FAILURE','Beta fit reached numerical parameter boundary')
 k<-ncol(d);diagnostics<-list(converged=TRUE,log_likelihood=v$ll,frequency_total=total,n_active_rows=length(y),mean_rank=k,precision_rank=ncol(z),maximum_mean_score=score,covariance_type='OBSERVED_INFORMATION_IID',solver='BFGS',solver_success=fit$convergence==0,gradient_evaluations=unname(fit$counts[['gradient']]),max_iter=max_iter,tolerance=tolerance,effective_score_tolerance=max(sqrt(tolerance),1e-7))
 model<-q$model;model$parameters<-c(model$parameters,list(mean_link=mean_link,precision_link=precision_link,mean_coefficients=as.list(fit$par[seq_len(k)]),precision_coefficients=as.list(fit$par[k+seq_len(ncol(z))]),precision_feature_order=as.list(zz$feature_order),precision_feature_min=as.list(apply(zz$x[q$active,,drop=FALSE],2,min)),precision_feature_max=as.list(apply(zz$x[q$active,,drop=FALSE],2,max)),covariance=.cr_lgd_matrix_rows(covariance),covariance_type='OBSERVED_INFORMATION_IID'));model$precision_input_fingerprint<-.cr_hash(.cr_lgd_matrix_rows(zz$x));model$diagnostics<-diagnostics;.cr_fit_result(.cr_model(model),'lgd.fit_beta_lgd',diagnostics=diagnostics,context=context)
}

.cr_lgd_matrix_rows <- function(x) lapply(seq_len(nrow(x)),function(i)as.list(x[i,]))

predict_lgd<-function(fitted_model,X,feature_order,expected_target,default_condition,precision_design=NULL,precision_feature_order=NULL,quantile_levels=NULL,context=NULL){
 model<-.cr_model(fitted_model);p<-model$parameters;method<-model$method_id;context<-.cr_lgd_target_context(model$target,context,model$model_version)
 if(method=='lgd.fit_recovery_hurdle'){if(!is.null(precision_design)||!is.null(precision_feature_order)) .cr_error('FEATURE_MISMATCH','Recovery hurdle has no beta precision design');return(.cr_lgd_hurdle_prediction(model,X,feature_order,expected_target,default_condition,quantile_levels,context))}
 if(!(method%in%c('lgd.fit_fractional_lgd','lgd.fit_beta_lgd','lgd.fit_zero_one_inflated_lgd'))) .cr_error('UNSUPPORTED_MODEL','Unsupported frozen LGD estimator')
 if(!identical(as.list(feature_order),model$feature_order)||!identical(.cr_hash(expected_target),.cr_hash(model$target))||!identical(default_condition,'given_default')||!identical(p$default_condition,default_condition)) .cr_error('TARGET_MISMATCH','Feature order and physical conditional target must match the frozen model')
 des<-.cr_glm_design(X,feature_order,p$fit_intercept);x<-des$x;d<-des$d;n<-nrow(x);levels<-if(is.null(quantile_levels))NULL else .cr_numeric(quantile_levels,'quantile_levels',vector_only=TRUE)
 if(!is.null(levels)&&(any(levels<=0|levels>=1)||any(diff(levels)<=0))) .cr_error('INVALID_QUANTILE','Quantile levels must be strictly increasing inside (0,1)')
 lo<-.cr_lgd_parameter_vector(p$feature_min,'feature_min',allow_empty=TRUE,vector_only=TRUE);hi<-.cr_lgd_parameter_vector(p$feature_max,'feature_max',allow_empty=TRUE,vector_only=TRUE)
 if(length(lo)!=ncol(x)||length(hi)!=length(lo)||any(lo>hi)) .cr_error('INVALID_MODEL','Frozen feature support is malformed')
 outside<-if(ncol(x))rowSums(sweep(x,2,lo,'<')|sweep(x,2,hi,'>'))>0 else rep(FALSE,n)
 if(method=='lgd.fit_zero_one_inflated_lgd'){
  required<-c(boundary_gate='lgd.fit_fractional_lgd',one_gate='lgd.fit_fractional_lgd',interior_model='lgd.fit_beta_lgd');for(key in names(required))if(!identical(.cr_model(p[[key]])$method_id,unname(required[key]))) .cr_error('INVALID_MODEL','Inflated beta component method mismatch')
  gate<-predict_lgd(p$boundary_gate,X,feature_order,expected_target,default_condition);one<-predict_lgd(p$one_gate,X,feature_order,expected_target,default_condition);inside<-predict_lgd(p$interior_model,X,feature_order,expected_target,default_condition,precision_design,precision_feature_order)
  pb<-unlist(gate$value$mean_lgd);po<-unlist(one$value$mean_lgd);pi<-1-pb;p0<-pb*(1-po);p1<-pb*po;mu<-unlist(inside$value$mean_lgd);phi<-unlist(inside$value$precision);mean<-p1+pi*mu;quantiles<-NULL
  outside<-outside|unlist(gate$diagnostics$outside_marginal_training_range)|unlist(one$diagnostics$outside_marginal_training_range)|unlist(inside$diagnostics$outside_marginal_training_range)
  if(!is.null(levels))quantiles<-lapply(seq_len(n),function(i)as.list(vapply(levels,function(u)if(u<=p0[i])0 else if(u>=1-p1[i])1 else qbeta((u-p0[i])/pi[i],mu[i]*phi[i],(1-mu[i])*phi[i]),numeric(1))))
  value<-list(mean_lgd=as.list(mean),distribution='ZERO_ONE_INFLATED_BETA',zero_probability=as.list(p0),one_probability=as.list(p1),interior_probability=as.list(pi),interior_mean=as.list(mu),precision=as.list(phi),quantile_levels=if(is.null(levels))NULL else as.list(levels),quantiles=quantiles)
 }else{
  key<-if(method=='lgd.fit_fractional_lgd')'coefficients' else 'mean_coefficients';coef<-.cr_lgd_parameter_vector(p[[key]],key,vector_only=TRUE);if(length(coef)!=ncol(d)) .cr_error('INVALID_MODEL','Frozen mean coefficient dimension mismatch');eta<-as.vector(d%*%coef);if(any(!is.finite(eta))) .cr_error('NUMERICAL_FAILURE','LGD linear predictor outside finite range');mean<-plogis(eta)
  if(method=='lgd.fit_fractional_lgd'){
   if(!is.null(precision_design)||!is.null(precision_feature_order)) .cr_error('FEATURE_MISMATCH','Fractional mean has no precision design');if(!is.null(levels)) .cr_error('DISTRIBUTION_NOT_IDENTIFIED','A fractional conditional mean does not identify loss quantiles');if(!identical(p$link,'logit')) .cr_error('INVALID_MODEL','Frozen fractional mean link must be logit')
   value<-list(mean_lgd=as.list(mean),distribution=NULL,quantile_levels=NULL,quantiles=NULL)
  }else{
   if(!identical(p$mean_link,'logit')||!identical(p$precision_link,'log')) .cr_error('INVALID_MODEL','Frozen beta links must be logit/log');zz<-.cr_lgd_precision_design(precision_design,precision_feature_order,n)
   if(!identical(as.list(zz$feature_order),p$precision_feature_order)) .cr_error('FEATURE_MISMATCH','Precision feature order must match frozen model');gamma<-.cr_lgd_parameter_vector(p$precision_coefficients,'precision_coefficients',vector_only=TRUE);zl<-.cr_lgd_parameter_vector(p$precision_feature_min,'precision_feature_min',allow_empty=TRUE,vector_only=TRUE);zh<-.cr_lgd_parameter_vector(p$precision_feature_max,'precision_feature_max',allow_empty=TRUE,vector_only=TRUE)
   if(length(gamma)!=ncol(zz$d)||length(zl)!=ncol(zz$x)||length(zh)!=length(zl)||any(zl>zh)) .cr_error('INVALID_MODEL','Frozen precision coefficient or support dimension mismatch')
   if(ncol(zz$x))outside<-outside|rowSums(sweep(zz$x,2,zl,'<')|sweep(zz$x,2,zh,'>'))>0
   phi<-exp(as.vector(zz$d%*%gamma));if(any(!is.finite(phi))||any(phi<=0)||any(mean<=0|mean>=1)) .cr_error('NUMERICAL_FAILURE','Beta distribution reached a numerical parameter boundary')
   quantiles<-if(is.null(levels))NULL else lapply(seq_len(n),function(i)as.list(qbeta(levels,mean[i]*phi[i],(1-mean[i])*phi[i])))
   value<-list(mean_lgd=as.list(mean),distribution='BETA',precision=as.list(phi),quantile_levels=if(is.null(levels))NULL else as.list(levels),quantiles=quantiles)
  }
 }
 .cr_result(value,'lgd.predict_lgd','loss_fraction',context,provenance=model$provenance,diagnostics=list(model_id=model$model_id,model_version=model$model_version,model_fingerprint=.cr_hash(model),default_condition=default_condition,outside_marginal_training_range=as.list(outside)),limitations='Conditional on default and the frozen target. Marginal training ranges do not establish joint support; fractional means alone do not identify a loss distribution.')
}
fit_zero_one_inflated_lgd<-function(X_train,lgd_targets,feature_order,component_spec,target,training,model_id,model_version,precision_design=NULL,precision_feature_order=NULL,weights=NULL,weight_type='frequency',fit_intercept=TRUE,max_iter=500,tolerance=1e-10,context=NULL){
 if(!.cr_object(component_spec)||!identical(.cr_hash(component_spec),.cr_hash(list(boundary_origin='structural',gate_link='logit')))) .cr_error('COMPONENT_SPEC','Declare structural (not rounded/censored) endpoints and logit gates')
 q<-.cr_lgd_fit_inputs(X_train,lgd_targets,feature_order,fit_intercept,weights,weight_type,target,training,model_id,model_version,'lgd.fit_zero_one_inflated_lgd');x<-q$x;y<-q$y;w<-q$w;active<-q$active
 if(any(y<0|y>1)) .cr_error('INVALID_LGD_TARGET','Inflated beta targets must lie in [0,1]');boundary<-y==0|y==1;interior<-!boundary
 if(!all(vapply(list(y==0,y==1,interior),function(m)any(active&m),logical(1)))) .cr_error('INSUFFICIENT_COMPONENT_SUPPORT','Positive frequency support required for zero, one and interior components')
 zz<-.cr_lgd_precision_design(precision_design,precision_feature_order,length(y));common<-list(feature_order=feature_order,target=target,training=training,model_version=model_version,weight_type=weight_type,fit_intercept=fit_intercept,max_iter=max_iter,tolerance=tolerance)
 gate<-do.call(fit_fractional_lgd,c(list(X_train=x,lgd_targets=as.numeric(boundary),weights=w,link='logit',covariance='HC0',model_id=paste0(model_id,':boundary')),common))
 one<-do.call(fit_fractional_lgd,c(list(X_train=x[boundary,,drop=FALSE],lgd_targets=y[boundary],weights=w[boundary],link='logit',covariance='HC0',model_id=paste0(model_id,':one')),common))
 inside<-do.call(fit_beta_lgd,c(list(X_train=x[interior,,drop=FALSE],lgd_targets=y[interior],weights=w[interior],mean_link='logit',precision_link='log',model_id=paste0(model_id,':interior'),precision_design=if(is.null(precision_design))NULL else zz$x[interior,,drop=FALSE],precision_feature_order=zz$feature_order),common))
 model<-q$model;model$parameters<-c(model$parameters,list(component_spec=component_spec,boundary_gate=gate$model,one_gate=one$model,interior_model=inside$model));diagnostics<-list(converged=TRUE,component_frequency=list(zero=sum(w[y==0]),one=sum(w[y==1]),interior=sum(w[interior])),log_likelihood=gate$diagnostics$quasi_log_likelihood+one$diagnostics$quasi_log_likelihood+inside$diagnostics$log_likelihood,conditional_independence='Likelihood factors by observed endpoint membership; component scores use their own observation subsets');model$diagnostics<-diagnostics;.cr_fit_result(.cr_model(model),'lgd.fit_zero_one_inflated_lgd',diagnostics=diagnostics,context=context)
}

.cr_lgd_parameter_vector<-function(x,name,allow_empty=FALSE,vector_only=TRUE){if(is.list(x)&&is.null(names(x))&&all(vapply(x,function(a)is.numeric(a)&&length(a)==1L&&!is.object(a),logical(1))))x<-if(length(x))unlist(x,use.names=FALSE) else numeric();.cr_numeric(x,name,allow_empty=allow_empty,vector_only=vector_only)}

.cr_lgd_target_context<-function(target,context,model_version){ctx<-.cr_result(NULL,'lgd.context',context=context)$context;for(key in c('horizon','time_unit','probability_measure','conditioning','currency'))if(!is.null(ctx[[key]])&&!is.null(target[[key]])&&!isTRUE(all.equal(ctx[[key]],target[[key]]))) .cr_error('TARGET_MISMATCH',paste('Calculation context conflicts with frozen LGD',key));if(!is.null(ctx$model_version)&&!identical(ctx$model_version,model_version)) .cr_error('TARGET_MISMATCH','Calculation context model version differs');ctx}

estimate_downturn_lgd<-function(fitted_lgd_model,baseline_covariates,adverse_covariates,aggregation_weights,feature_order,expected_target,downturn_definition,baseline_precision_design=NULL,adverse_precision_design=NULL,precision_feature_order=NULL,model_draws=NULL,uncertainty_contract=NULL,interval_level=.95,context=NULL){
 model<-.cr_model(fitted_lgd_model);if(!.cr_object(downturn_definition)) .cr_error('DOWNTURN_POLICY','Explicit dated scenario-selection policy required');policy<-downturn_definition;.cr_data_required(policy,c('definition_id','version','selection_basis','baseline_scenario_id','adverse_scenario_id','known_at','as_of','unit_ids','extrapolation_policy'))
 for(key in c('definition_id','version','selection_basis','baseline_scenario_id','adverse_scenario_id')) .cr_string(policy[[key]],key,'DOWNTURN_POLICY');if(.cr_data_date(policy$known_at,'known_at')>.cr_data_date(policy$as_of,'as_of')||.cr_data_date(model$training$known_at,'training.known_at')>.cr_data_date(policy$as_of,'as_of')) .cr_error('DOWNTURN_DATE','Selection policy and fitted model must be known at scenario evaluation');if(!(policy$extrapolation_policy%in%c('error','report'))) .cr_error('DOWNTURN_POLICY','Declare error or report for marginal support violations')
 ids<-if(is.list(policy$unit_ids))unlist(policy$unit_ids,use.names=FALSE) else policy$unit_ids;if(!is.character(ids)||!length(ids)||anyNA(ids)||any(!nzchar(ids))||anyDuplicated(ids)) .cr_error('DOWNTURN_POLICY','Distinct matched portfolio unit IDs required');policy$unit_ids<-as.list(ids);w<-.cr_numeric(aggregation_weights,'aggregation_weights',vector_only=TRUE);if(length(w)!=length(ids)||any(w<0)||!any(w>0)) .cr_error('INVALID_WEIGHTS','Nonnegative matched portfolio weights with positive total required');w<-w/max(w);w<-w/.cr_loss_sum(w)
 ctx<-.cr_lgd_target_context(model$target,context,model$model_version);if(!is.null(ctx$as_of)&&!identical(ctx$as_of,policy$as_of)) .cr_error('DOWNTURN_DATE','Context and policy evaluation dates differ')
 pair<-function(frozen){if(.cr_data_date(frozen$training$known_at,'training.known_at')>.cr_data_date(policy$as_of,'as_of')) .cr_error('DOWNTURN_DATE','Model draw was not known at scenario evaluation');results<-list(predict_lgd(frozen,baseline_covariates,feature_order,expected_target,'given_default',baseline_precision_design,precision_feature_order,context=context),predict_lgd(frozen,adverse_covariates,feature_order,expected_target,'given_default',adverse_precision_design,precision_feature_order,context=context));if(any(vapply(results,function(r)length(r$value$mean_lgd)!=length(ids),logical(1)))) .cr_error('INCOMPATIBLE_SHAPE','Scenario rows must match portfolio unit IDs and weights');support<-lapply(results,function(r)unlist(r$diagnostics$outside_marginal_training_range));if(policy$extrapolation_policy=='error'&&any(vapply(support,function(s)any(s&w>0),logical(1)))) .cr_error('DOWNTURN_SUPPORT','Positive-weight scenario rows exceed frozen marginal training ranges');means<-vapply(results,function(r).cr_loss_sum(.cr_loss_multiply(w,unlist(r$value$mean_lgd))),numeric(1));list(means=means,results=results,support=support)}
 fitted<-pair(model);means<-fitted$means;uplift<-.cr_loss_sum(c(means[2],-means[1]));uncertainty<-list(status='NOT_ESTIMATED',interval_level=NULL,baseline_interval=NULL,adverse_interval=NULL,uplift_interval=NULL,draw_count=0)
 if(is.null(model_draws)){if(!is.null(uncertainty_contract)) .cr_error('DOWNTURN_UNCERTAINTY','Uncertainty contract without paired model draws is not an estimate')}else{
 if(!is.list(model_draws)||length(model_draws)<2L||!.cr_object(uncertainty_contract)) .cr_error('DOWNTURN_UNCERTAINTY','At least two paired frozen model draws and a declared uncertainty contract required');.cr_data_required(uncertainty_contract,c('source','interpretation'));if(!(uncertainty_contract$source%in%c('bootstrap','posterior','user_supplied'))) .cr_error('DOWNTURN_UNCERTAINTY','Declare bootstrap/posterior/user_supplied draws and their inferential interpretation');.cr_string(uncertainty_contract$interpretation,'interpretation','DOWNTURN_UNCERTAINTY');level<-.cr_lgd_scalar(interval_level,'interval_level');if(level<=0||level>=1) .cr_error('DOWNTURN_UNCERTAINTY','Interval level must be inside (0,1)')
 draws<-lapply(model_draws,function(draw){frozen<-.cr_model(draw);if(!identical(frozen$method_id,model$method_id)||!identical(.cr_hash(frozen$target),.cr_hash(model$target))||!identical(frozen$feature_order,model$feature_order)) .cr_error('TARGET_MISMATCH','Uncertainty draws must share model family and target/feature contract');if(model$method_id=='lgd.fit_recovery_hurdle'&&!identical(.cr_hash(frozen$parameters$stage_spec),.cr_hash(model$parameters$stage_spec))) .cr_error('RECOVERY_STAGE','Paired uncertainty draws must share the frozen residual payout stage');m<-pair(frozen)$means;c(m,.cr_loss_sum(c(m[2],-m[1])))});q<-apply(do.call(rbind,draws),2,stats::quantile,probs=c((1-level)/2,(1+level)/2),type=7,names=FALSE);uncertainty<-list(status='SUPPLIED_PAIRED_MODEL_DRAWS',interval_level=level,baseline_interval=as.list(q[,1]),adverse_interval=as.list(q[,2]),uplift_interval=as.list(q[,3]),draw_count=length(draws),contract=uncertainty_contract)
 }
 .cr_result(list(baseline_lgd=means[1],downturn_lgd=means[2],difference=uplift,unit_ids=as.list(ids),normalized_weights=as.list(w),baseline_unit_lgd=fitted$results[[1]]$value$mean_lgd,adverse_unit_lgd=fitted$results[[2]]$value$mean_lgd,uncertainty=uncertainty),'lgd.estimate_downturn_lgd','loss_fraction',context,provenance=model$provenance,diagnostics=list(model_fingerprint=.cr_hash(model),policy_fingerprint=.cr_hash(policy),downturn_definition=policy,baseline_outside_marginal_range=as.list(fitted$support[[1]]),adverse_outside_marginal_range=as.list(fitted$support[[2]]),adverse_effect_nonnegative=uplift>=0),limitations='Scenario selection and economic adversity are explicit user policy. The model may imply a negative adverse-minus-baseline difference; no regulatory floor or automatic surcharge is imposed. Marginal ranges do not prove joint support or causal identification. Supplied paired draws retain their declared interpretation; no confidence guarantee is manufactured.')
}
